mapper.insert:
INSERT INTO video_play_segment (segment_id, session_id, segment, create_time, update_time)
VALUES (#{id.segmentId}, #{id.sessionId}, int4range(#{startWatchTimeInSeconds}, #{endWatchTimeInSeconds}), #{createTime}, #{updateTime})
ON CONFLICT (session_id, segment_id)
DO UPDATE SET segment = int4range(lower(video_play_segment.segment), #{endWatchTimeInSeconds}), update_time = #{updateTime}
    WHERE NOT video_play_segment.segment @> int4range(#{startWatchTimeInSeconds}, #{endWatchTimeInSeconds});

mapper.select:
SELECT time_bucket, SUM(upper(segment) - lower(segment)) AS value FROM video_play_segment play_segment JOIN video_play_session play_session ON play_session.id = play_segment.session_id AND play_session.master_id = #{masterId}
AND play_session.video_id IN
#{videoId}
RIGHT JOIN
( SELECT #{filter.start}::timestamp with time zone AS time_bucket UNION SELECT #{filter.end}::timestamp with time zone ) AS time_bucket ON play_segment.update_time <= time_bucket
generate_series(#{filter.start}, #{filter.end}, concat(#{filter.step}, ' second')::interval) AS time_bucket ON play_segment.update_time >= time_bucket AND play_segment.update_time < time_bucket + concat(#{filter.step}, ' second')::interval
GROUP BY time_bucket ORDER BY time_bucket;

SELECT time_bucket, SUM(upper(segment) - lower(segment)) / COUNT(DISTINCT play_session.user_id)::double precision AS value FROM video_play_segment play_segment JOIN video_play_session play_session ON play_session.id = play_segment.session_id AND play_session.master_id = #{masterId}
AND play_session.video_id IN
#{videoId}
RIGHT JOIN
( SELECT #{filter.start}::timestamp with time zone AS time_bucket UNION SELECT #{filter.end}::timestamp with time zone ) AS time_bucket ON play_segment.update_time <= time_bucket
generate_series(#{filter.start}, #{filter.end}, concat(#{filter.step}, ' second')::interval) AS time_bucket ON play_segment.update_time >= time_bucket AND play_segment.update_time < time_bucket + concat(#{filter.step}, ' second')::interval
GROUP BY time_bucket ORDER BY time_bucket;
